-- Exercise: a credit counter with a bug.
-- A sender may have up to 4 requests in flight. `take` spends a credit when
-- a request goes out, `give` returns one when a response comes back.
-- Invariant: credits + inflight == 4, shown as the output `io_ok`.
-- There are two bugs. The first stops it compiling: read the error.
-- After fixing that, simulate and find the cycle where io_ok drops.
xblue module mkCredits;
  input Bool reset;
  input Bool send;
  input Bool resp;
  Reg#(Bit#(3)) credits  <- mkReg(4);
  Reg#(Bit#(8)) sent     <- mkReg(0);
  Reg#(Bit#(8)) returned <- mkReg(0);

  Bit#(8) inflight = sent - returned;
  Bit#(8) c8       = zeroExtend(credits);
  Bool canSend = send && inflight < 5;   -- at most 4 in flight
  Bool canResp = resp && inflight != 0;

  method Bool    io_ok       = c8 + inflight == 4;
  method Bit#(3) io_credits  = credits;
  method Bit#(8) io_inflight = inflight;

  rule take (canSend);
    credits <= credits - 1;
    sent    <= sent + 1;
  endrule

  rule give (canResp);
    credits  <= credits + 1;
    returned <= returned + 1;
  endrule

  rule clear (reset);
    credits  <= 4;
    sent     <= 0;
    returned <= 0;
  endrule

  schedule (take ∥ give) ≫ clear;
endmodule

-- Once it compiles, prove it too: below `endmodule`, write `step` (one cycle
-- of `mkCredits.design.cycle`), a `spec` that tells the cycle one rule at a
-- time, and a theorem that `credits + inflight == 4` holds in every cycle.

